window.Vocab = (function () {
  const lista = [];
  const mapa = new Map();
  let listo = false;
  function init() {
    if (listo || !window.VOCAB_ES) return;
    listo = true;
    const nrm = (window.Banco && window.Banco.norm) || ((s) => s);
    const arr = window.VOCAB_ES.split('\n');
    for (let i = 0; i < arr.length; i++) {
      const w = arr[i]; if (!w) continue;
      const n = nrm(w);
      const e = { w, n, rank: i };
      lista.push(e);
      if (!mapa.has(n)) mapa.set(n, e);
    }
  }
  return {
    get list() { init(); return lista; },
    ready() { init(); return lista.length > 0; },
    has(n) { init(); return mapa.has(n); },
    palabra(n) { init(); const e = mapa.get(n); return e ? e.w : null; },
    where(fn, maxRank) {
      init();
      const out = [];
      const hasta = maxRank == null ? lista.length : Math.min(maxRank, lista.length);
      for (let i = 0; i < hasta; i++) if (fn(lista[i])) out.push(lista[i]);
      return out;
    },
  };
})();
